<div class="heading"><div><div class="eyebrow">البيانات الأساسية</div><h1>الأقسام والمراحل والمواد</h1><p>افصل العام الدراسي والمراحل والمواد قبل ترشيح الطلبة.</p></div></div>
<?php $sections=['year'=>['academic_years','الأعوام الدراسية'],'department'=>['departments','الأقسام والمدارس'],'stage'=>['stages','المراحل الدراسية'],'subject'=>['subjects','المواد الامتحانية']];foreach($sections as $kind=>[$table,$label]):$edit=null;if(($_GET['kind']??'')===$kind&&!empty($_GET['edit']))$edit=owned($table,(int)$_GET['edit']);?>
<section class="card"><h2><?=h($label)?></h2><?php if(can('write')):?><form method="post" class="toolbar"><?=csrf()?><input type="hidden" name="action" value="save"><input type="hidden" name="kind" value="<?=h($kind)?>"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><?php field('الاسم','name',$edit['name']??'');if(in_array($kind,['stage','subject'],true))selectf('القسم','department_id',opts('departments'),$edit['department_id']??'');if($kind==='subject'){ $options=[];foreach(rows('SELECT s.*,d.name AS department FROM stages s JOIN departments d ON d.id=s.department_id WHERE s.institution_id=? ORDER BY d.name,s.name',[inst()]) as $s)$options[$s['id']]=$s['department'].' / '.$s['name'];selectf('المرحلة','stage_id',$options,$edit['stage_id']??'');}?><button><?=$edit?'حفظ التعديل':'إضافة'?></button><?php if($edit):?><a href="?page=structure">إلغاء</a><?php endif;?></form><?php endif;?>
<div class="table-wrap"><table><tr><th>الاسم</th><?php if(in_array($kind,['stage','subject'],true)):?><th>القسم</th><?php endif;if($kind==='subject'):?><th>المرحلة</th><?php endif;?><th>إجراء</th></tr><?php foreach(rows("SELECT * FROM $table WHERE institution_id=? ORDER BY id",[inst()]) as $r):?><tr><td><?=h($r['name'])?></td><?php if(isset($r['department_id'])):?><td><?=h(owned('departments',(int)$r['department_id'])['name'])?></td><?php endif;if(isset($r['stage_id'])):?><td><?=h(owned('stages',(int)$r['stage_id'])['name'])?></td><?php endif;?><td><?php if(can('write')):?><a href="?page=structure&kind=<?=h($kind)?>&edit=<?=(int)$r['id']?>">تعديل</a> <form method="post" class="inline" data-confirm="حذف السجل غير المرتبط فقط؟"><?=csrf()?><input type="hidden" name="action" value="delete"><input type="hidden" name="table" value="<?=h($table)?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="ghost danger">حذف</button></form><?php endif;?></td></tr><?php endforeach;?></table></div></section><?php endforeach;?>
